import { createRequire } from "node:module";
import assert from "node:assert/strict";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
const { chromium } = createRequire(import.meta.url)("playwright");
const [base, executablePath, token] = process.argv.slice(2);
const evidence = mkdtempSync(join(tmpdir(), "DK1564-conclusion-ui-browser-"));
const browser = await chromium.launch({ executablePath, headless: true });
const context = await browser.newContext({ viewport: { width: 390, height: 844 } });
try {
  assert.equal((await context.request.post(base + "/api/login", { data: { token } })).status(), 200);
  const page = await context.newPage();
  page.on("pageerror", (e) => console.error("pageerror:", e.message));
  const open = async (hash) => { await page.goto(base + "/#demo/" + hash); };
  const source = async (id) => { await open("draft/" + id); await page.getByText("Задачи разбора", { exact: true }).waitFor(); };
  const confirm = async (count) => {
    const btn = page.getByRole("button", { name: "Подтвердить разбор", exact: true });
    await btn.waitFor();
    assert.equal(await btn.isEnabled(), true);
    const response = page.waitForResponse(r => r.url().endsWith("/drafts/prepared/confirm") && r.request().method() === "POST");
    await btn.click();
    const reply = await response;
    assert.equal(reply.status(), 200, await reply.text());
    const body = await reply.json();
    assert.equal(body.results.length, count);
    await page.waitForURL(/#demo\/drafts(\/chat\/|$)/);
    return body;
  };
  await open("drafts");
  await page.locator("tr.secband .shead").filter({ hasText: "Согласовать заведение" }).waitFor();
  await page.locator("tr.secband .shead").filter({ hasText: "Разбор и оформление" }).waitFor();
  const sectionRows = page.locator("tbody.tsec tr.dsrow");
  assert.equal(await sectionRows.count(), 4);
  assert.equal(await sectionRows.locator("button.dpick").count(), 0);
  for (const row of await sectionRows.all()) assert.equal(await row.locator("td").count(), 8);
  const p1row = sectionRows.filter({ has: page.locator("td.id", { hasText: "XR-005" }) });
  await p1row.locator("td.id").click();
  await page.waitForURL(/#demo\/draft\/XR-005(\/chat\/|$)/);
  await page.getByText("Задачи разбора", { exact: true }).waitFor();
  await page.getByText("Заключение разбора", { exact: true }).waitFor();
  assert.equal(await page.locator("div.srow").count(), 0);
  await open("draft/XR-005/prepared/p1");
  await page.waitForURL(/#demo\/draft\/XR-005$/);
  await page.getByText("Заключение разбора", { exact: true }).waitFor();
  await confirm(2);
  // Переход меняет URL раньше, чем refresh прочитает и отрисует список.
  console.log("rows immediately after navigation:", await page.locator("tbody.tsec tr.dsrow").count());
  await page.waitForFunction(() => document.querySelectorAll("tbody.tsec tr.dsrow").length === 3, null, { timeout: 10000 });
  assert.equal(await page.locator("tbody.tsec tr.dsrow").count(), 3);
  assert.equal(await page.locator("tbody.tsec tr.dsrow td.id").filter({ hasText: "XR-005" }).count(), 0);
  await source("XR-005");
  await page.getByText("История разбора", { exact: true }).waitFor();
  assert.equal(await page.getByRole("button", { name: "Подтвердить разбор", exact: true }).count(),0);
  assert.equal(await page.locator(".draft-idea").count(),0);
  assert.equal(await page.locator("div.srow").count(), 0);
  await page.getByText("Заключение разбора", { exact: true }).waitFor();
  for (const [id,count] of [["XR-006",2],["XR-007",1]]) { await source(id); await confirm(count); }
  await open("XR-001");
  await page.locator(".ffold .foldh").filter({ hasText: "Из черновика" }).click();
  await page.locator(".ffold").filter({ hasText: "третья карточка" }).first().waitFor();
  await page.getByRole("link", { name: "черновик XR-006", exact: true }).click();
  await page.waitForURL(/#demo\/draft\/XR-006/);
  await page.getByText("История разбора", { exact: true }).waitFor();
  await open("XR-001");
  await page.getByLabel("заголовок задачи XR-001").waitFor();
  const normalFields = await page.locator("#groups .tedit, #groups .rcard, #groups .duebox, #groups .fbody, #groups .dcard").count();
  await page.screenshot({ path: join(evidence,"normal-read.png"), fullPage:true });
  const normalTitle = await page.getByLabel("заголовок задачи XR-001").inputValue();
  await page.getByRole("button", { name: "Править задачу", exact: true }).click();
  await page.getByLabel("заголовок задачи XR-001").fill("Отменённое название");
  await page.getByRole("button", { name: "Отменить правку", exact: true }).click();
  await page.waitForFunction(title => document.querySelector("#groups .tedit")?.value === title, normalTitle);
  assert.equal(await page.getByLabel("заголовок задачи XR-001").inputValue(), normalTitle);
  await page.getByLabel("срок задачи XR-001, дата", { exact:true }).fill("2026-12-20");
  const normalSaved = page.waitForResponse(r=>r.url().endsWith("/tasks/XR-001") && r.request().method()==="PATCH");
  await page.getByRole("button", {name:"Сохранить",exact:true}).click();
  assert.equal((await normalSaved).status(),200);
  await page.getByLabel("срок задачи XR-001, дата", {exact:true}).waitFor();
  await open("draft/XR-010/prepared/p5");
  await page.locator("#groups .idbig").filter({hasText:/XR-/}).waitFor();
  const number = (await page.locator("#groups .idbig").innerText()).trim();
  const preparedTitle = page.getByLabel("заголовок задачи " + number, {exact:true});
  await preparedTitle.waitFor();
  assert.equal(await page.locator("#groups .tedit, #groups .rcard, #groups .duebox, #groups .fbody, #groups .dcard").count(),normalFields);
  assert.equal(await preparedTitle.inputValue(),"баг доставки ленты");
  assert.ok((await page.locator("#groups .rbig").innerText()).includes("42"));
  const richChips = (await page.locator(".tchips .chip").allInnerTexts()).join(" | ");
  assert.ok(richChips.includes("На согласовании") && richChips.includes("Проверка с вашим участием"),richChips);
  assert.equal(await page.getByRole("button", {name:/Чат по задаче/}).count(),0);
  await page.screenshot({ path: join(evidence,"prepared-read.png"), fullPage:true });
  for (const selector of [".pedit", ".pshort", ".parea", ".darm"]) assert.equal(await page.locator("#groups " + selector).count(),0,selector);
  for (const label of ["Исход","Вернуться до","Довод разбора","Причина","Свойства задачи"]) assert.equal(await page.getByLabel(label,{exact:true}).count(),0,label);
  for (const label of ["Выполнить","Продолжить","Начать разговор"]) assert.equal(await page.getByRole("button",{name:label,exact:true}).count(),0,label);
  await page.getByRole("button", { name: "Править задачу", exact: true }).click();
  assert.equal(await page.getByRole("button",{name:"Сохранить",exact:true}).count(),0,"карандаш требует фиктивного Save");
  await page.screenshot({ path: join(evidence,"prepared-edit.png"), fullPage:true });
  await preparedTitle.fill("Отменённая подготовленная задача");
  await page.getByRole("button",{name:"Отменить правку",exact:true}).click();
  await page.waitForFunction(() => document.querySelector("#groups .tedit")?.value === "баг доставки ленты");
  assert.equal(await page.getByLabel("заголовок задачи " + number,{exact:true}).inputValue(),"баг доставки ленты");
  await page.getByRole("button", { name: "Править задачу", exact: true }).click();
  await page.getByLabel("заголовок задачи " + number,{exact:true}).fill("баг доставки ленты после правки");
  await page.getByLabel("срок задачи " + number + ", дата",{exact:true}).fill("2026-12-21");
  await page.getByLabel("контроль задачи " + number + ", за сколько дней до срока проверка работ",{exact:true}).fill("3");
  const preparedSaved = page.waitForResponse(r=>r.url().endsWith("/XR-010/prepared") && r.request().method()==="PUT");
  await page.getByRole("button",{name:"Сохранить",exact:true}).click();
  const preparedResp = await preparedSaved;
  assert.equal(preparedResp.status(),200,await preparedResp.text());
  await page.locator("#groups .fview").waitFor({state:"visible"});
  assert.equal(await page.getByRole("button",{name:"Сохранить",exact:true}).count(),0);
  await page.setViewportSize({width:1440,height:1000});
  await page.screenshot({ path: join(evidence,"prepared-desktop.png"), fullPage:true });
  await page.setViewportSize({width:390,height:844});
  const richView = await (await context.request.get(base + "/api/projects/demo/drafts/XR-010/prepared")).json();
  const richTask = richView.state.proposals.find(p=>p.outcome==="add");
  assert.equal(richTask.title,"баг доставки ленты после правки"); assert.equal(richTask.control,"3");
  await source("XR-010");
  const rich = await confirm(1);
  const ids = rich.results.flatMap(r=>r.ids || []);
  assert.ok(ids.length);
  await page.locator("#flashes").filter({ hasText:ids[0] }).waitFor();
  await source("XR-008");
  await page.getByText("Разбор ничего не подготовил. Можно подготовить задачу вручную.", { exact: true }).waitFor();
  await page.getByRole("button", { name: "Подготовить вручную", exact: true }).click();
  await page.waitForURL(/#demo\/draft\/XR-008\/prepared\/new/);
  await page.locator("#groups .tedit").fill("ручная задача");
  await page.locator("#groups .fbody textarea").fill(richTask.text);
  await page.locator("#groups .tchips .pick").filter({has:page.locator(".pl",{hasText:/^тип$/})}).locator("select").selectOption("bug");
  await page.locator("#groups .tchips .pick").filter({has:page.locator(".pl",{hasText:/^цена$/})}).locator("select").selectOption("L");
  const rankValues = [25,5,3,5,4];
  for (let i=0;i<rankValues.length;i++) await page.locator("#groups .rcard select").nth(i).selectOption(String(rankValues[i]));
  const saved = page.waitForResponse(r=>r.url().endsWith("/XR-008/prepared") && r.request().method()==="PUT");
  await page.getByRole("button", { name: "Сохранить задачу", exact: true }).click();
  const savedResp = await saved;
  assert.equal(savedResp.status(), 200, await savedResp.text());
  const savedBody = await savedResp.json();
  const manualID = Object.values(savedBody.assigned || {})[0];
  assert.match(manualID || "", /^XR-[0-9]+$/);
  await page.waitForURL(new RegExp("#demo/draft/XR-008/prepared/" + manualID + "(/chat/)?$"));
  assert.equal(await page.getByRole("button", {name:"Подтвердить",exact:true}).count(),0);
  await source("XR-008"); await confirm(1);
  await source("XR-009");
  await page.getByText("Не удалось разобрать запись. Можно повторить разбор.", { exact: true }).waitFor();
  assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);
  await page.setViewportSize({width:1440,height:1000});
  await source("XR-006"); await page.getByText("История разбора",{exact:true}).waitFor();
  assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);
  const archived = await context.request.post(base + "/__archive");
  assert.equal(archived.status(),200,await archived.text());
  await open("XR-001");
  await page.locator(".ffold .foldh").filter({hasText:"Из черновика"}).click();
  await page.getByRole("link",{name:"черновик XR-006",exact:true}).click();
  await page.getByText("История разбора",{exact:true}).waitFor();
  console.log(JSON.stringify({sources:4,whole:true,history:true,attach:true,manual:true,evidence,sharedForm:true,normalEdit:true,preparedEdit:true,cancel:true,forbiddenControls:false,widths:[390,1440]}));
} finally { await context.close(); await browser.close(); }
